  "gradient.backdrop": {
    cssVar: "--by-gradient-backdrop",
    type: "gradient",
    tier: "semantic",
    description: "The app background of the layered look, painted once on the app root (background or background-image: var(--by-gradient-backdrop), or the bg-(image:--by-gradient-backdrop) utility): the two backdrop glows over the canvas colour, under every translucent layer. Where the glows are the canvas colour it shows a flat canvas. Not behind a single card or control, and not where a colour is needed: tools without gradients (Figma, Monaco) read its solid colour, color.bg.canvas unless the theme changes it.",
    values: { "light": "radial-gradient(1100px 700px at 8% 0%, oklch(0.93 0.0344 282.5) 0%, transparent 60%), radial-gradient(1000px 800px at 100% 35%, oklch(0.955 0.0154 190) 0%, transparent 60%), linear-gradient(oklch(0.975 0.006 275), oklch(0.975 0.006 275))", "dark": "radial-gradient(1100px 700px at 8% 0%, oklch(0.32 0.0743 282.5) 0%, transparent 60%), radial-gradient(1000px 800px at 100% 35%, oklch(0.32 0.0495 190) 0%, transparent 60%), linear-gradient(oklch(0.21 0.0084 275), oklch(0.21 0.0084 275))" },
  },
